def edf(tasks, horizon):
    # tasks: [(이름, 실행시간 C, 주기=상대 마감 P)]
    jobs, timeline = [], []
    for t in range(horizon):
        for name, c, p in tasks:
            if t % p == 0:  # 주기마다 새 작업 도착
                jobs.append([t + p, name, c])  # 마감·이름·잔여
        if any(d <= t for d, _, _ in jobs):
            return 'deadline miss at %d' % t
        if not jobs:
            timeline.append('-')  # 유휴
            continue
        job = min(jobs)  # 마감 가장 이른 작업 (매 시점 재선택=선점)
        job[2] -= 1
        timeline.append(job[1])
        if job[2] == 0:
            jobs.remove(job)
    return timeline
# 예: [(T1,1,4), (T2,2,6), (T3,3,8)] U=0.958 → 성공
